const a={running:["运行中","ok"],active:["运行中","ok"],started:["运行中","ok"],stopped:["已停止","err"],inactive:["已停止","err"],dead:["已停止","err"],failed:["异常","err"],starting:["启动中","warn"],activating:["启动中","warn"],stopping:["停止中","warn"],deactivating:["停止中","warn"],"not-installed":["未安装","muted"],unknown:["未知","warn"]},i={connected:["已连接","ok"],connecting:["连接中","warn"],"auth-failed":["认证失败","err"],"tls-failed":["TLS 失败","err"],"config-error":["配置错误","err"],"proxy-error":["映射异常","err"],unreachable:["不可达","err"],disconnected:["已断开","err"],timeout:["连接超时","warn"],"not-configured":["未配置","warn"],stopped:["已停止","err"],unknown:["待确认","warn"]};function r(n,t){const o=String(n||"").toLowerCase(),e=t[o];return e?{raw:n,label:e[0],tone:e[1]}:{raw:n,label:n||"未知",tone:"warn"}}const c=n=>r(n,a),s=n=>r(n,i);export{s as c,c as s};
